    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newRoundImplementation) public payable {
        address beforeImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.updateRoundImplementation(payable(newRoundImplementation)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address afterImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;

        assert(afterImpl == beforeImpl);
    }
}

