// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function _run(address newRoundImplementation) internal {
        address beforeImpl;
        try c.roundImplementation() returns (address __r) { beforeImpl = __r; } catch { return; }
        bool reverted;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterImpl;
        try c.roundImplementation() returns (address __r) { afterImpl = __r; } catch { return; }
        assertTrue(afterImpl == beforeImpl);
    }

    function testFuzz_run(address newRoundImplementation) public {
        vm.assume(newRoundImplementation.code.length == 0 && uint160(newRoundImplementation) > 0xffff && newRoundImplementation != address(this) && newRoundImplementation != address(c) && newRoundImplementation != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newRoundImplementation != 0x000000000000000000636F6e736F6c652e6c6f67 && newRoundImplementation != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newRoundImplementation != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newRoundImplementation);
    }

    receive() external payable {}
}
